-- 85 Eredivisie/Bundesliga home fixtures; German December dates are only provisional windows.
on conflict (fixture_key) do update set country=excluded.country,zone=excluded.zone,cluster=excluded.cluster,city=excluded.city,league=excluded.league,home=excluded.home,away=excluded.away,date=excluded.date,time=excluded.time,provisional=excluded.provisional,highlight=excluded.highlight,source_url=excluded.source_url,date_window_start=excluded.date_window_start,date_window_end=excluded.date_window_end,updated_at=now();
